use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use uuid::Uuid;

/// Parsed IDS rule (Suricata/Snort-style)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IdsRule {
    pub sid: i32,
    pub category: String,
    pub severity: String,
    pub message: String,
    pub rule_text: String,
    pub enabled: bool,
    pub source: String,
}

/// Alert generated by IDS rule match
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IdsAlert {
    pub rule_id: Option<Uuid>,
    pub sid: i32,
    pub timestamp: DateTime<Utc>,
    pub src_ip: String,
    pub src_port: u16,
    pub dest_ip: String,
    pub dest_port: u16,
    pub protocol: String,
    pub payload: Option<String>,
    pub severity: String,
    pub community_id: Option<String>,
}

/// EVE JSON log event from Suricata
#[derive(Debug, Clone, Deserialize)]
pub struct EveJsonEvent {
    pub timestamp: Option<String>,
    pub event_type: Option<String>,
    pub src_ip: Option<String>,
    pub src_port: Option<u16>,
    pub dest_ip: Option<String>,
    pub dest_port: Option<u16>,
    pub proto: Option<String>,
    pub alert: Option<EveAlert>,
    pub community_id: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct EveAlert {
    pub signature_id: Option<i32>,
    pub signature: Option<String>,
    pub category: Option<String>,
    pub severity: Option<i32>,
}

/// IDS Engine: rule storage, matching, and thresholding
pub struct IdsEngine {
    rules: Vec<IdsRule>,
    rule_index: HashMap<i32, usize>,  // sid -> index into rules
    /// Alert count per SID in current window (for thresholding)
    threshold_counters: HashMap<i32, ThresholdState>,
}

struct ThresholdState {
    count: u64,
    window_start: DateTime<Utc>,
}

impl IdsEngine {
    pub fn new() -> Self {
        Self {
            rules: Vec::new(),
            rule_index: HashMap::new(),
            threshold_counters: HashMap::new(),
        }
    }

    /// Load rules from database result set
    pub fn load_rules(&mut self, rules: Vec<IdsRule>) {
        self.rule_index.clear();
        for (i, rule) in rules.iter().enumerate() {
            self.rule_index.insert(rule.sid, i);
        }
        self.rules = rules;
        tracing::info!("Loaded {} IDS rules", self.rules.len());
    }

    /// Parse an EVE JSON event and produce an alert if a rule matches
    pub fn process_eve_event(&mut self, event: &EveJsonEvent) -> Option<IdsAlert> {
        let alert_data = event.alert.as_ref()?;
        let sid = alert_data.signature_id?;

        // Check if we have this rule and it's enabled
        if let Some(&idx) = self.rule_index.get(&sid) {
            let rule = &self.rules[idx];
            if !rule.enabled {
                return None;
            }

            // Thresholding: max 100 alerts per SID per 5-minute window
            let now = Utc::now();
            let entry = self.threshold_counters.entry(sid).or_insert(ThresholdState {
                count: 0,
                window_start: now,
            });
            let window_seconds = (now - entry.window_start).num_seconds();
            if window_seconds > 300 {
                entry.count = 0;
                entry.window_start = now;
            }
            entry.count += 1;
            if entry.count > 100 {
                return None; // Suppressed
            }

            return Some(IdsAlert {
                rule_id: None, // Will be set by caller from DB lookup
                sid,
                timestamp: now,
                src_ip: event.src_ip.clone().unwrap_or_default(),
                src_port: event.src_port.unwrap_or(0),
                dest_ip: event.dest_ip.clone().unwrap_or_default(),
                dest_port: event.dest_port.unwrap_or(0),
                protocol: event.proto.clone().unwrap_or_else(|| "unknown".into()),
                payload: None,
                severity: match alert_data.severity.unwrap_or(3) {
                    1 => "critical".into(),
                    2 => "high".into(),
                    3 => "medium".into(),
                    _ => "low".into(),
                },
                community_id: event.community_id.clone(),
            });
        }

        None
    }

    /// Get rule by SID
    pub fn get_rule(&self, sid: i32) -> Option<&IdsRule> {
        self.rule_index.get(&sid).map(|&idx| &self.rules[idx])
    }

    /// Count of loaded rules
    pub fn rule_count(&self) -> usize {
        self.rules.len()
    }

    /// Count of enabled rules
    pub fn enabled_count(&self) -> usize {
        self.rules.iter().filter(|r| r.enabled).count()
    }

    /// Classify alert severity distribution
    pub fn severity_distribution(&self) -> HashMap<String, usize> {
        let mut dist = HashMap::new();
        for rule in &self.rules {
            *dist.entry(rule.severity.clone()).or_insert(0) += 1;
        }
        dist
    }
}

impl Default for IdsEngine {
    fn default() -> Self {
        Self::new()
    }
}
